using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;
public static class BalancePlaytest {
 public sealed class Cohort {public string name;public double start,learn,edit,click;public int workers,batch;public string[] route;}
 static readonly string[] Metal={"function-Heat","function-Polish","material-5","function-Plate","material-7"};
 static readonly string[] Magic={"material-6","function-Charge","function-Rune","material-9","function-Refine"};
 static readonly string[] Speed={"material-4","function-Fuel","function-Wrap","speed-1","speed-2","speed-3","speed-4","speed-5"};
 static string[] Join(params string[][] parts)=>parts.SelectMany(x=>x).Distinct().ToArray();
 static Cohort[] Groups()=>new[]{
 new Cohort{name="novice",start=1200,learn=120,edit=240,click=12,workers=2,batch=10,route=Join(new[]{ForgeTechnology.AutomationRoot},Metal,new[]{"function-Lucky"},Speed.Take(6).ToArray(),Magic,new[]{ForgeTechnology.MasterCommission})},
 new Cohort{name="intermediate",start=600,learn=60,edit=120,click=5,workers=4,batch=30,route=Join(new[]{ForgeTechnology.AutomationRoot,"function-Lucky"},Metal.Take(4).ToArray(),Speed.Take(6).ToArray(),Metal,Magic,Speed,new[]{ForgeTechnology.MasterCommission})},
 new Cohort{name="expert",start=240,learn=20,edit=45,click=1,workers=16,batch=100,route=Join(new[]{ForgeTechnology.AutomationRoot,"function-Lucky","function-Heat"},Speed,Metal,Magic,new[]{"function-Protect","function-Curse",ForgeTechnology.MasterCommission})}};
 public sealed class Recipe {public string name,code;public ForgeProduct product;public double seconds;public int cost,price;public double Rate(double click)=>(price-cost)/(seconds+click);}
 static Recipe Evaluate(string name,string code,ForgeTechnology tech,int speed,uint seed){var e=BlueprintRuntime.Evaluate(code,int.MaxValue,100000,name,seed,Enumerable.Range(2,8).ToDictionary(x=>x,x=>100000L),tech,context:new ForgeRunContext{Speed=speed,Seed=(int)seed});if(e.error!=null||e.product==null)return null;return new Recipe{name=name,code=code,product=e.product,seconds=e.steps.Sum(x=>x.duration)+e.steps.Count/60d,cost=ForgeTechnology.Offers.Where(x=>x.Kind==ForgePurchaseKind.Material).Sum(x=>x.Price*e.product.Data.materials[x.Material]),price=ForgePricing.Quote(e.product).SalePrice};}
 public static List<Recipe> Recipes(ForgeTechnology t,int speed,uint seed,bool full=true,bool curse=true){
 var result=new List<Recipe>();bool Has(BlueprintFeature f)=>t.Owns(f);
 // Enumerate practical combinations; all candidates pass the real parser, research gates and crafting engine.
 foreach(int material in new[]{1,7}) for(int mask=0;mask<128;mask++){
 if(!t.MaterialAvailable(material))continue;
 bool plate=(mask&1)!=0,charge=(mask&2)!=0,rune=(mask&4)!=0,bone=(mask&8)!=0,magic=(mask&16)!=0,seal=(mask&32)!=0,resonance=(mask&64)!=0;
 if(plate&&!Has(BlueprintFeature.Plate)||charge&&!Has(BlueprintFeature.Charge)||rune&&!Has(BlueprintFeature.Rune)||bone&&!Has(BlueprintFeature.Refine)||magic&&!Has(BlueprintFeature.Magic)||seal&&!Has(BlueprintFeature.Wrap)||resonance&&!Has(BlueprintFeature.Resonate))continue;
 if(!full&&(magic||seal||resonance))continue;
 string code="p=1("+material+")\n";
 if(magic)code+="401(p)\n";code+="2(p,7)\n3(p)\n";if(magic)code+="3(p)\n3(p)\n";code+="4(p,3)\n";
 if(plate||bone)code+="6(p)\n";if(plate)code+="7(p)\n";
 if(bone)code+="b=1(9)\n10(b,p,100,13)\n5(p,b)\n";else code+="5(p,2)\n";
 if(charge)code+="9(p,1)\n9(p,1)\n9(p,1)\n";
 if(rune)code+="for r in [7,8,9]:\n    211(p,r)\n";
 if(seal)code+="for s in [1,2,3,1,2,3]:\n    201(p,s)\nfor s in [3,2,1,3,2,1]:\n    202(p,s)\n";
 if(resonance)code+="c=1(6)\nlo=1\nhi=9\nwhile lo <= hi:\n    mid=(lo+hi)//2\n    2(c,mid)\n    cmp=501(c)\n    if cmp==0:\n        break\n    if cmp<0:\n        lo=mid+1\n    else:\n        hi=mid-1\n4(c,0)\n5(p,c)\n";
 if(Has(BlueprintFeature.Lucky))code+="777(778(),p)\n";
 if(curse&&Has(BlueprintFeature.Curse)&&Has(BlueprintFeature.Protect))code+="667(p)\n666(p)\n";
 var recipe=Evaluate("m"+material+"-"+mask,code+"!p",t,speed,seed);if(recipe!=null)result.Add(recipe);
 }return result;
 }
 sealed class Run {
 public ForgeTechnology tech=new ForgeTechnology();public ForgeBlacksmiths smith=new ForgeBlacksmiths();public int gold=100,iron=10,diamonds,sales,crafts,failures;public ForgeMaterialStock[] stocks=Array.Empty<ForgeMaterialStock>();public double seconds,engine,thinking,interaction,end=-1,quarter=-1,half=-1,threequarter=-1;public long revenue;public Cohort group;public uint seed;public List<string> events=new List<string>();Recipe recipe;int sinceShop;string recipeKey="";bool ended,clockReady,completingSmith;double gameSeconds;
 void AddTime(double n,int kind){if(clockReady){double from=8+gameSeconds*24/600,to=from+n*24/600;for(int day=(int)(from/24)+2;day<=1+(int)(to/24);day++)smith.Tick(day,(day-1)*24);gameSeconds+=n;smith.Tick(1+(int)(to/24),to);}seconds+=n;if(kind==0)engine+=n;else if(kind==1)thinking+=n;else interaction+=n;}
 public Run(Cohort c,int s){group=c;seed=(uint)s;smith.randomState=(uint)s;AddTime(c.start,1);smith.Normalize(8);smith.Tick(1,8);clockReady=true;}
 void Pick(){int speed=Math.Max(1,tech.MaxSpeedLevel);var options=Recipes(tech,speed,seed,group.name!="novice");recipe=options.OrderByDescending(r=>r.Rate(group.click*(tech.Owns(BlueprintFeature.AutoSell)?.5:1))).First();if(recipe.name!=recipeKey){AddTime(group.edit,1);recipeKey=recipe.name;events.Add(Line("recipe",recipe.name+" net="+(recipe.price-recipe.cost)+"G seconds="+recipe.seconds.ToString("F2")));}}
 string Line(string type,string detail)=>group.name+","+seed+","+seconds.ToString("F2",System.Globalization.CultureInfo.InvariantCulture)+","+type+","+detail.Replace(",",";")+","+gold+","+sales+","+tech.ExportNodes().Length+","+smith.smiths.Count;
 void Purchase(ForgeTechnology.Offer o){if(!tech.TryPurchase(o,ref gold,ref iron,ref stocks,false,out var error))throw new Exception(error+" "+o.Id);events.Add(Line("purchase",o.Id+" cost="+o.Price));AddTime(group.learn,1);int n=tech.ExportNodes().Length,total=ForgeTechnology.Offers.Count(x=>x.Kind!=ForgePurchaseKind.Material);if(quarter<0&&n>=Math.Ceiling(total*.25))quarter=seconds;if(half<0&&n>=Math.Ceiling(total*.5))half=seconds;if(threequarter<0&&n>=Math.Ceiling(total*.75))threequarter=seconds;Pick();}
 bool Prepare(Recipe r){int required=ForgeTechnology.Offers.Where(x=>x.Kind==ForgePurchaseKind.Material).Sum(x=>x.Price*(int)Math.Max(0,r.product.Data.materials[x.Material]-tech.Stock(x,iron,stocks)));if(gold<required)return false;foreach(var o in ForgeTechnology.Offers.Where(x=>x.Kind==ForgePurchaseKind.Material)){int needed=r.product.Data.materials[o.Material];int missing=(int)Math.Max(0,needed-tech.Stock(o,iron,stocks));if(missing>0&&!tech.TryPurchase(o,ref gold,ref iron,ref stocks,false,out var error,missing))return false;}return true;}
 void Consume(Recipe r){iron-=r.product.Data.materials[1];foreach(var s in stocks)s.count-=r.product.Data.materials[s.material];}
 void Complete(Recipe r,int id){double hours=8+gameSeconds*24/600;int day=1+(int)(hours/24);smith.Tick(day,hours);smith.Chances(id,hours,out var destroy,out var great);double roll=smith.Next(1000000)/1000000d;crafts++;if(roll<destroy){failures++;return;}var d=r.product.Data;int copies=1;if(roll<destroy+great){copies=2;d.smithSaleMultiplier=1.25+smith.Next(20001)/10000d;iron+=d.materials[1];foreach(var s in stocks)s.count+=d.materials[s.material];}var p=new ForgeProduct(r.name,0,true,r.product.Traits,0,r.product.IronConsumed,r.product.Material,d,r.seconds);for(int i=0;i<copies;i++){var shop=new ForgeShop();int item=shop.Add(p);if(!shop.TrySell(item,ref gold,out var sold))throw new Exception("sale failed");sales++;revenue+=ForgePricing.Quote(sold).SalePrice;diamonds+=sold.DiamondReward;}if(!ended&&ForgeCampaign.CanComplete(tech,p)){ended=true;end=seconds;events.Add(Line("ending",r.name));}}
 void Wave(bool final=false){if(recipe==null)Pick();var r=final?Evaluate("master",ForgeCampaignChecks.Final,tech,Math.Max(1,tech.MaxSpeedLevel),seed):recipe;if(r==null)throw new Exception("missing recipe");var jobs=new List<int>();int workers=tech.Owns(ForgeTechnology.AutomationRoot)?Math.Min(group.workers,smith.smiths.Count):1;for(int id=0;id<workers;id++){if(!Prepare(r))break;Consume(r);jobs.Add(id);}if(jobs.Count==0){r=Evaluate("recovery","p=1(1)\n2(p,7)\n3(p)\n4(p,0)\n!p",tech,Math.Max(1,tech.MaxSpeedLevel),seed);if(!Prepare(r))throw new Exception("BANKRUPT "+group.name+" "+gold);Consume(r);jobs.Add(0);events.Add(Line("recovery","basic blade"));}AddTime(r.seconds,0);AddTime(group.click*(tech.Owns(BlueprintFeature.AutoSell)?.5:1),2);sinceShop+=jobs.Count;if(sinceShop>=group.batch){AddTime(group.name=="novice"?20:group.name=="intermediate"?10:4,2);sinceShop=0;}foreach(int id in jobs)Complete(r,id);if(!completingSmith&&tech.Owns(BlueprintFeature.Lucky)&&smith.hireTier<5&&ForgeBlacksmiths.Counts[smith.hireTier+1]<=group.workers&&diamonds>=ForgeBlacksmiths.HireCosts[smith.hireTier]){smith.Hire(ref diamonds,8+gameSeconds*24/600);events.Add(Line("hire","tier="+smith.hireTier));AddTime(group.edit,1);}if(seconds>7*24*3600||crafts>5000000)throw new Exception("STALLED");}
 void Buy(string id){if(tech.Owns(id))return;var o=ForgeTechnology.Find(id);foreach(var p in o.Parents)Buy(p);if(recipe==null)Pick();while(gold<o.Price+Math.Max(100,recipe.cost*Math.Min(group.workers,smith.smiths.Count)*2))Wave();Purchase(o);}
 public double SmithCompletion(){completingSmith=true;recipe=Recipes(tech,Math.Max(1,tech.MaxSpeedLevel),seed,true,false).OrderByDescending(r=>r.product.DiamondReward/(r.seconds+group.click*.5)).First();int research=ForgeBlacksmiths.FavorResearchCost+ForgeBlacksmiths.PositionResearchCost+ForgeBlacksmiths.DemandResearchCost;while(diamonds<research)Wave();diamonds-=research;smith.favorUnlocked=smith.positionUnlocked=smith.demandUnlocked=true;while(smith.hireTier<5){int cost=ForgeBlacksmiths.HireCosts[smith.hireTier];while(diamonds<cost)Wave();if(smith.hireTier<5&&diamonds>=ForgeBlacksmiths.HireCosts[smith.hireTier])smith.Hire(ref diamonds,8+gameSeconds*24/600);}return seconds;}
 public string Play(bool all){foreach(string id in group.route)Buy(id);while(!ended)Wave(true);if(all){foreach(var o in ForgeTechnology.Offers.Where(x=>x.Kind!=ForgePurchaseKind.Material))Buy(o.Id);}return group.name+","+seed+","+end.ToString("F2")+","+seconds.ToString("F2")+","+engine.ToString("F2")+","+thinking.ToString("F2")+","+interaction.ToString("F2")+","+quarter.ToString("F2")+","+half.ToString("F2")+","+threequarter.ToString("F2")+","+sales+","+crafts+","+failures+","+gold+","+smith.smiths.Count;}
 }
 public static string RunBatch(string label,int seeds=10){string dir="Docs/QA/Balance/"+label;Directory.CreateDirectory(dir);var rows=new List<string>{"cohort,seed,ending_seconds,all_tree_seconds,engine_seconds,assumed_learning_seconds,assumed_interaction_seconds,tree25_seconds,tree50_seconds,tree75_seconds,sales,crafts,failures,gold,workers,smith_tree_seconds"};var events=new List<string>{"cohort,seed,seconds,event,detail,gold,sales,nodes,workers"};foreach(var c in Groups())for(int s=1;s<=seeds;s++){var run=new Run(c,s);string row=run.Play(true);double smithTime=run.SmithCompletion();rows.Add(row+","+smithTime.ToString("F2"));if(s==1)events.AddRange(run.events);}File.WriteAllLines(dir+"/runs.csv",rows);File.WriteAllLines(dir+"/events.csv",events);File.WriteAllLines(dir+"/prices.csv",ForgeTechnology.Offers.Select(o=>o.Id+","+o.Price));return string.Join("\n",rows);}
 public static string Rewards(){var tech=new ForgeTechnology();tech.Restore(Array.Empty<BlueprintFeature>(),ForgeTechnology.Offers.Where(x=>x.Kind!=ForgePurchaseKind.Material).Select(x=>x.Id).ToArray());var list=new List<string>();foreach(var r in Recipes(tech,1,1))list.Add(r.name+","+r.price+","+r.cost+","+r.seconds.ToString("F2")+","+r.Rate(0).ToString("F2"));return string.Join("\n",list);}
 public static string RewardTable(string label){var t=new ForgeTechnology();t.Restore(Array.Empty<BlueprintFeature>(),ForgeTechnology.Offers.Where(o=>o.Kind!=ForgePurchaseKind.Material).Select(o=>o.Id).ToArray());string basic="p=1(1)\n2(p,7)\n3(p)\n4(p,3)\n5(p,2)\n";var cases=new Dictionary<string,string>{{"basic",basic},{"plate",basic+"6(p)\n7(p)\n"},{"star",basic.Replace("1(1)","1(7)")},{"charge",basic+"9(p,1)\n9(p,1)\n9(p,1)\n"},{"runes",basic+"for r in [7,8,9]:\n    211(p,r)\n"},{"magic",basic.Replace("2(p,7)","401(p)\n2(p,7)").Replace("3(p)","3(p)\n3(p)\n3(p)")},{"dragon",basic.Replace("5(p,2)","6(p)\nb=1(9)\n10(b,p,100,13)\n5(p,b)")},{"lucky",basic+"777(778(),p)\n"},{"protected_curse",basic+"667(p)\n666(p)\n"},{"seals",basic+"for s in [1,2,3,1,2,3]:\n    201(p,s)\nfor s in [3,2,1,3,2,1]:\n    202(p,s)\n"},{"resonance",basic+"c=1(6)\nlo=1\nhi=9\nwhile lo<=hi:\n    mid=(lo+hi)//2\n    2(c,mid)\n    cmp=501(c)\n    if cmp==0:\n        break\n    if cmp<0:\n        lo=mid+1\n    else:\n        hi=mid-1\n4(c,0)\n5(p,c)\n"},{"final",ForgeCampaignChecks.Final.Replace("!p","")}};var rows=new List<string>{"recipe,sale,materials,net,seconds,net_per_second"};foreach(var pair in cases){var rs=Enumerable.Range(1,20).Select(seed=>Evaluate(pair.Key,pair.Value+"!p",t,1,(uint)seed)).ToArray();if(rs.Any(r=>r==null))throw new Exception(pair.Key);rows.Add(pair.Key+","+rs.Average(r=>r.price).ToString("F2")+","+rs.Average(r=>r.cost).ToString("F2")+","+rs.Average(r=>r.price-r.cost).ToString("F2")+","+rs.Average(r=>r.seconds).ToString("F2")+","+rs.Average(r=>r.Rate(0)).ToString("F2"));}Directory.CreateDirectory("Docs/QA/Balance/"+label);File.WriteAllLines("Docs/QA/Balance/"+label+"/rewards.csv",rows);return string.Join("\n",rows);}

 public static string RouteSweep(string label){var basis=Groups()[2];var routes=new Dictionary<string,string[]>{{"expert_speed3_rush",Join(new[]{ForgeTechnology.AutomationRoot,"function-Lucky","function-Heat"},Speed.Take(6).ToArray(),Metal,Magic,new[]{ForgeTechnology.MasterCommission})},{"expert_speed_rush",Join(new[]{ForgeTechnology.AutomationRoot,"function-Lucky","function-Heat"},Speed,Metal,Magic,new[]{ForgeTechnology.MasterCommission})},{"expert_metal_rush",Join(new[]{ForgeTechnology.AutomationRoot,"function-Lucky"},Metal,Magic,new[]{ForgeTechnology.MasterCommission})},{"expert_magic_rush",Join(new[]{ForgeTechnology.AutomationRoot,"function-Lucky","function-Heat","material-6","function-Inspect","function-Magic","function-Resonate"},Speed,Metal,Magic,new[]{ForgeTechnology.MasterCommission})}};var rows=new List<string>{"route,seed,ending_seconds,total_seconds,engine_seconds,assumed_learning_seconds,assumed_interaction_seconds,tree25_seconds,tree50_seconds,tree75_seconds,sales,crafts,failures,gold,workers"};foreach(var pair in routes)for(int seed=1;seed<=3;seed++){var c=new Cohort{name=pair.Key,start=basis.start,learn=basis.learn,edit=basis.edit,click=basis.click,workers=basis.workers,batch=basis.batch,route=pair.Value};rows.Add(new Run(c,seed).Play(false));}File.WriteAllLines("Docs/QA/Balance/"+label+"/routes.csv",rows);return string.Join("\n",rows);}

 public static string Sensitivity(){var rows=new List<string>{"cohort,seed,ending_seconds,total_seconds,engine_seconds,assumed_learning_seconds,assumed_interaction_seconds,tree25_seconds,tree50_seconds,tree75_seconds,sales,crafts,failures,gold,workers"};foreach(var c in Groups())foreach(double factor in new[]{.5,1.5}){var v=new Cohort{name=c.name,start=c.start*factor,learn=c.learn*factor,edit=c.edit*factor,click=c.click*factor,workers=c.workers,batch=c.batch,route=c.route};rows.Add(new Run(v,1).Play(false).Replace(c.name+",",c.name+"_human_time_x"+factor+","));}File.WriteAllLines("Docs/QA/Balance/final/sensitivity.csv",rows);return string.Join("\n",rows);}

}
